function docandtee_block_category( $categories, $post ) {
	return array_merge(
		$categories,
		array(
			array(
				'slug' => 'docandtee-blocks',
				'title' => __( 'Custom Blocks by Doc and Tee', 'docandtee-blocks' ),
			),
		)
	);
}
add_filter( 'block_categories_all', 'docandtee_block_category', 10, 2);


